package api

import (
	"net/http"

	"github.com/gin-gonic/gin"

	"github.com/luwa07832/feature-flag-service/internal/store"
)

// NewRouter wires the public HTTP surface. Every entry keeps the error shape
// described in README.md: a single top-level error object with code/message.
func NewRouter(st *store.Store) *gin.Engine {
	gin.SetMode(gin.ReleaseMode)
	router := gin.New()
	router.Use(gin.Recovery())

	router.GET("/healthz", func(c *gin.Context) {
		if err := st.Ping(); err != nil {
			c.JSON(http.StatusServiceUnavailable, gin.H{"error": gin.H{"code": "storage_unavailable", "message": "database is not available"}})
			return
		}
		c.JSON(http.StatusOK, gin.H{"status": "ok", "database": "ok"})
	})

	v1 := router.Group("/api/v1")
	{
		v1.POST("/environments", createEnvironment(st))
		v1.POST("/flags", createFlag(st))
		v1.GET("/flags", listFlags(st))
		v1.GET("/compare/:flagKey", compareFlags(st))
		v1.GET("/environments/:environment/evaluate", evaluate(st))
		v1.GET("/environments/:environment/evaluate-at", evaluateAt(st))
		v1.GET("/environments/:environment/changes", getChanges(st))
		v1.GET("/environments/:environment/flags/:flagKey/explain", explainFlag(st))
		v1.GET("/environments/:environment/flags/:flagKey/history", getHistory(st))
		v1.PUT("/environments/:environment/flags/:flagKey/config", putConfig(st))
		v1.DELETE("/environments/:environment/flags/:flagKey/config", deleteConfig(st))
	}

	router.NoRoute(func(c *gin.Context) {
		c.JSON(http.StatusNotFound, gin.H{"error": gin.H{"code": "route_not_found", "message": "no route matches this path"}})
	})
	return router
}
package api

import (
	"regexp"

	"github.com/gin-gonic/gin"

	"github.com/luwa07832/feature-flag-service/internal/store"
	"github.com/luwa07832/feature-flag-service/internal/timeutil"
)

// KeyPattern is the published identifier grammar for environments and flags.
var KeyPattern = regexp.MustCompile(`^[a-z0-9_-]{1,64}$`)

// ErrorCode is the vocabulary of the single top-level error object every
// entry returns.
const (
	codeInvalidRequest      = "InvalidRequest"
	codeEnvironmentNotFound = "EnvironmentNotFound"
	codeFlagNotFound        = "FlagNotFound"
	codeAlreadyExists       = "AlreadyExists"
	codeInvalidTimestamp    = "InvalidTimestamp"
	codeInvalidMarker       = "InvalidMarker"
	codeStorageUnavailable  = "storage_unavailable"
)

func fail(c *gin.Context, status int, code, message string) {
	c.JSON(status, gin.H{"error": gin.H{"code": code, "message": message}})
}

// windowJSON renders a time window; nil timestamps stay null.
func windowJSON(startsAt, endsAt *int64) gin.H {
	var starts, ends any
	if startsAt != nil {
		starts = timeutil.Format(*startsAt)
	}
	if endsAt != nil {
		ends = timeutil.Format(*endsAt)
	}
	return gin.H{"starts_at": starts, "ends_at": ends}
}

func configJSON(r store.ConfigRecord) gin.H {
	return gin.H{
		"flag_key":    r.FlagKey,
		"environment": r.Environment,
		"version":     r.Version,
		"enabled":     r.Enabled,
		"percentage":  r.Percentage,
		"window":      windowJSON(r.StartsAt, r.EndsAt),
		"changed_at":  timeutil.Format(r.ChangedAt),
		"tombstone":   r.Tombstone,
	}
}
package api

import (
	"encoding/json"
	"errors"
	"io"
	"net/http"

	"github.com/gin-gonic/gin"

	"github.com/luwa07832/feature-flag-service/internal/store"
	"github.com/luwa07832/feature-flag-service/internal/timeutil"
)

type createKeyRequest struct {
	Key string `json:"key"`
}

type putConfigRequest struct {
	Enabled    bool    `json:"enabled"`
	Percentage int     `json:"percentage"`
	Window     *window `json:"window"`
}

type window struct {
	StartsAt *string `json:"starts_at"`
	EndsAt   *string `json:"ends_at"`
}

func createEnvironment(st *store.Store) gin.HandlerFunc {
	return func(c *gin.Context) {
		var req createKeyRequest
		if !decodeStrict(c, &req) || !validKey(c, req.Key) {
			return
		}
		env, err := st.CreateEnvironment(req.Key)
		if err != nil {
			writeStoreError(c, err)
			return
		}
		c.JSON(http.StatusCreated, gin.H{
			"key":        env.Key,
			"created_at": timeutil.Format(env.CreatedAt),
		})
	}
}

func createFlag(st *store.Store) gin.HandlerFunc {
	return func(c *gin.Context) {
		var req createKeyRequest
		if !decodeStrict(c, &req) || !validKey(c, req.Key) {
			return
		}
		flag, err := st.CreateFlag(req.Key)
		if err != nil {
			writeStoreError(c, err)
			return
		}
		c.JSON(http.StatusCreated, gin.H{
			"key":        flag.Key,
			"created_at": timeutil.Format(flag.CreatedAt),
		})
	}
}

func putConfig(st *store.Store) gin.HandlerFunc {
	return func(c *gin.Context) {
		environment := c.Param("environment")
		flagKey := c.Param("flagKey")
		if !validPathKeys(c, environment, flagKey) {
			return
		}
		var req putConfigRequest
		if !decodeStrict(c, &req) {
			return
		}
		if req.Percentage < 0 || req.Percentage > 100 {
			fail(c, http.StatusBadRequest, codeInvalidRequest, "percentage must be between 0 and 100")
			return
		}
		startsAt, endsAt, ok := parseWindow(c, req.Window)
		if !ok {
			return
		}
		if !referencedResourcesExist(c, st, environment, flagKey) {
			return
		}
		record, err := st.PutConfig(store.PutConfigInput{
			FlagKey:     flagKey,
			Environment: environment,
			Enabled:     req.Enabled,
			Percentage:  req.Percentage,
			StartsAt:    startsAt,
			EndsAt:      endsAt,
		})
		if err != nil {
			writeStoreError(c, err)
			return
		}
		c.JSON(http.StatusCreated, configJSON(*record))
	}
}

func deleteConfig(st *store.Store) gin.HandlerFunc {
	return func(c *gin.Context) {
		environment := c.Param("environment")
		flagKey := c.Param("flagKey")
		if !validPathKeys(c, environment, flagKey) {
			return
		}
		if !referencedResourcesExist(c, st, environment, flagKey) {
			return
		}
		record, err := st.DeleteConfig(flagKey, environment)
		if err != nil {
			writeStoreError(c, err)
			return
		}
		c.JSON(http.StatusOK, configJSON(*record))
	}
}

func decodeStrict(c *gin.Context, dst any) bool {
	decoder := json.NewDecoder(c.Request.Body)
	decoder.DisallowUnknownFields()
	if err := decoder.Decode(dst); err != nil {
		if errors.Is(err, io.EOF) {
			fail(c, http.StatusBadRequest, codeInvalidRequest, "request body is required")
			return false
		}
		fail(c, http.StatusBadRequest, codeInvalidRequest, "request body could not be parsed")
		return false
	}
	if decoder.Decode(&struct{}{}) != io.EOF {
		fail(c, http.StatusBadRequest, codeInvalidRequest, "request body must contain a single JSON object")
		return false
	}
	return true
}

func validKey(c *gin.Context, key string) bool {
	if KeyPattern.MatchString(key) {
		return true
	}
	fail(c, http.StatusBadRequest, codeInvalidRequest, "key must match [a-z0-9_-]{1,64}")
	return false
}

func validPathKeys(c *gin.Context, keys ...string) bool {
	for _, key := range keys {
		if !KeyPattern.MatchString(key) {
			fail(c, http.StatusBadRequest, codeInvalidRequest, "environment and flag keys must match [a-z0-9_-]{1,64}")
			return false
		}
	}
	return true
}

func parseWindow(c *gin.Context, w *window) (*int64, *int64, bool) {
	if w == nil {
		return nil, nil, true
	}
	var startsAt, endsAt *int64
	if w.StartsAt != nil {
		parsed, err := timeutil.Parse(*w.StartsAt)
		if err != nil {
			fail(c, http.StatusBadRequest, codeInvalidTimestamp, "window.starts_at must be an RFC 3339 timestamp")
			return nil, nil, false
		}
		startsAt = &parsed
	}
	if w.EndsAt != nil {
		parsed, err := timeutil.Parse(*w.EndsAt)
		if err != nil {
			fail(c, http.StatusBadRequest, codeInvalidTimestamp, "window.ends_at must be an RFC 3339 timestamp")
			return nil, nil, false
		}
		endsAt = &parsed
	}
	if startsAt != nil && endsAt != nil && *endsAt <= *startsAt {
		fail(c, http.StatusBadRequest, codeInvalidRequest, "window.ends_at must be later than window.starts_at")
		return nil, nil, false
	}
	return startsAt, endsAt, true
}

func referencedResourcesExist(c *gin.Context, st *store.Store, environment, flagKey string) bool {
	envExists, err := st.EnvironmentExists(environment)
	if err != nil {
		internalFailure(c)
		return false
	}
	if !envExists {
		fail(c, http.StatusNotFound, codeEnvironmentNotFound, "the environment does not exist")
		return false
	}
	flagExists, err := st.FlagExists(flagKey)
	if err != nil {
		internalFailure(c)
		return false
	}
	if !flagExists {
		fail(c, http.StatusNotFound, codeFlagNotFound, "the flag does not exist")
		return false
	}
	return true
}

func writeStoreError(c *gin.Context, err error) {
	switch {
	case errors.Is(err, store.ErrAlreadyExists):
		fail(c, http.StatusConflict, codeAlreadyExists, "the resource already exists")
	case errors.Is(err, store.ErrNotFound):
		fail(c, http.StatusNotFound, codeFlagNotFound, "no live configuration exists for the flag in the environment")
	default:
		fail(c, http.StatusInternalServerError, "internal_error", "the service could not complete the request")
	}
}

