+
+func TestCreateFlagLegacyRequestGetsEmptyDefinition(t *testing.T) {
+	h := newHarness(t)
+	body := h.must(t, http.MethodPost, "/api/v1/flags", `{"key":"checkout"}`)
+	if body["description"] != "" {
+		t.Errorf("description = %v, want empty", body["description"])
+	}
