+	if err != nil {
+		t.Fatalf("open: %v", err)
+	}
+	defer st.Close()

+	created, err := st.CreateFlag("checkout", "old", []string{"old"})
+	if err != nil {
+		t.Fatalf("create: %v", err)
+	}
